#include <stdio.h>

int val[32];
int nxt[32];
int used = 0;
int head = -1;

int alloc_node(int v) {
    val[used] = v;
    nxt[used] = -1;
    return used++;
}

void push_back(int v) {
    int n = alloc_node(v);
    if (head == -1) { head = n; return; }
    int cur = head;
    while (nxt[cur] != -1) cur = nxt[cur];
    nxt[cur] = n;
}

void insert_after(int target, int v) {
    int cur = head;
    while (cur != -1 && val[cur] != target) cur = nxt[cur];
    if (cur == -1) return;
    int n = alloc_node(v);
    nxt[n] = nxt[cur];   /* new node adopts the tail... */
    nxt[cur] = n;        /* ...then the target adopts the new node */
}

void remove_value(int v) {
    if (head == -1) return;
    if (val[head] == v) { head = nxt[head]; return; }
    int cur = head;
    while (nxt[cur] != -1 && val[nxt[cur]] != v) cur = nxt[cur];
    if (nxt[cur] != -1) nxt[cur] = nxt[nxt[cur]];
}

void reverse_list() {
    int prev = -1;
    int cur = head;
    while (cur != -1) {
        int next = nxt[cur];   /* remember where we were going */
        nxt[cur] = prev;       /* flip the arrow */
        prev = cur;
        cur = next;
    }
    head = prev;
}

void print_list() {
    int cur = head;
    while (cur != -1) {
        printf("%d ", val[cur]);
        cur = nxt[cur];
    }
    printf("\n");
}

void emit_list() {
    printf("__NB_SET__ {\"key\":\"clist\",\"value\":[");
    int cur = head;
    while (cur != -1) {
        printf("%d", val[cur]);
        if (nxt[cur] != -1) printf(",");
        cur = nxt[cur];
    }
    printf("]}\n");
}

int main() {
    push_back(10); push_back(20); push_back(30); push_back(40);
    printf("initial:        "); print_list();

    insert_after(20, 25);
    printf("insert 25:      "); print_list();

    remove_value(30);
    printf("remove 30:      "); print_list();

    reverse_list();
    printf("reversed:       "); print_list();

    emit_list();
    return 0;
}

